using System.Globalization;

// Create culture objects
var enUs = new CultureInfo("en-US");
var frFr = new CultureInfo("fr-FR");
var esEs = new CultureInfo("es-ES");

DateTime sampleDate = new DateTime(2025, 7, 14);
decimal amount = 1234.56m;

// Long date formatting
Console.WriteLine(enUs.DateTimeFormat.LongDatePattern); // MMMM d, yyyy
Console.WriteLine(frFr.DateTimeFormat.LongDatePattern); // dddd d MMMM yyyy
Console.WriteLine(sampleDate.ToString("D", enUs));       // Monday, July 14, 2025
Console.WriteLine(sampleDate.ToString("D", frFr));       // lundi 14 juillet 2025

// Currency formatting
Console.WriteLine(amount.ToString("C", enUs)); // $1,234.56
Console.WriteLine(amount.ToString("C", frFr)); // 1 234,56 €
Console.WriteLine(amount.ToString("C", esEs)); // 1.234,56 €

// Number formatting
Console.WriteLine((9876.54).ToString("N", enUs)); // 9,876.54
Console.WriteLine((9876.54).ToString("N", frFr)); // 9 876,54

// After localization middleware sets the culture:
// Thread.CurrentThread.CurrentCulture = new CultureInfo("fr-FR");

DateTime now = DateTime.Now;
decimal price = 99.99m;

// These calls automatically use fr-FR formatting
Console.WriteLine(now.ToLongDateString()); // lundi 7 juillet 2025
Console.WriteLine(price.ToString("C"));     // 99,99 €
Console.WriteLine(price.ToString("P"));     // 9 999,00 %

// Explicit culture override is still possible
Console.WriteLine(price.ToString("C", new CultureInfo("en-US"))); // $99.99

using System.Globalization;

// All specific cultures (e.g., en-US, fr-FR)
var specificCultures = CultureInfo.GetCultures(CultureTypes.SpecificCultures);
foreach (var culture in specificCultures.OrderBy(c => c.DisplayName))
{
    Console.WriteLine($"{culture.Name,-10} {culture.DisplayName,-30} {culture.NativeName}");
}

// Output (abbreviated):
// en-US     English (United States)         English (United States)
// fr-FR     French (France)                 français (France)
// es-ES     Spanish (Spain)                 español (España)
// de-DE     German (Germany)                Deutsch (Deutschland)
// ja-JP     Japanese (Japan)                日本語 (日本)
